// Three large-subface clips; generated from FixOcclusion.cginc.
export const fixGLSL = /* glsl */`
// Generated by Tools/Nonconvex/build_subfaces.py; numpy only.
// One large equilateral subface per back-facing neighbor: three planes total.
const vec4 FixShadowCaps[3]=vec4[3](
vec4(1.243449788e-14, 0.3568220898, -0.4670861795, 0.8090169944),
vec4(0.3090169944, -0.1784110449, -0.4670861795, 0.8090169944),
vec4(-0.3090169944, -0.1784110449, -0.4670861795, 0.8090169944)
);
const float FixShadowOffsets[3]=float[3](-0.04774575141, -0.04774575141, -0.04774575141);
const vec4 FixSubfaces[3]=vec4[3](
vec4(-9.00211164e-15, -0.8726779962, 0.1423503277, 0.4670861795),
vec4(-0.7557613141, 0.4363389981, 0.1423503277, 0.4670861795),
vec4(0.7557613141, 0.4363389981, 0.1423503277, 0.4670861795)
);
const float FixSubfaceThresholds[3]=float[3](0.1508450225, 0.1508450225, 0.1508450225);
const float _OcclusionEpsilon=0.000002;
struct FixClipData {
  vec3 side;
  vec3 rayDenominator;
  uint activeMask;
};
vec3 FixPrepareOne(int i, vec4 p, vec4 eyeVector, float sine) {
    vec4 cap=FixShadowCaps[i];
    float h=FixShadowOffsets[i];
    float capEye=dot(cap,eyeVector);
    float facing=capEye+sine*h;
    // Same signed 4D facing convention as CRFFacet. Only the back-facing
    // neighboring cap casts this large-subface clip boundary.
    if(facing<= 0.0) return vec3(0);
    vec4 face=FixSubfaces[i];
    float k=FixSubfaceThresholds[i];
    float faceEye=dot(face,eyeVector);
    vec4 clipNormal=(faceEye+sine*k)*cap-facing*face;
    float clipThreshold=h*faceEye-k*capEye;
    return vec3(dot(clipNormal,p)-clipThreshold,-capEye-sine*dot(cap,p),1);
}
FixClipData FixPrepareClips(vec4 p, vec4 eyeVector, float sine) {
  // Explicit components avoid non-addressable vector writes in Unity's CG compiler.
  vec3 a=FixPrepareOne(0,p,eyeVector,sine);
  vec3 b=FixPrepareOne(1,p,eyeVector,sine);
  vec3 c=FixPrepareOne(2,p,eyeVector,sine);
  FixClipData result;
  result.side=vec3(a.x,b.x,c.x);
  result.rayDenominator=vec3(a.y,b.y,c.y);
  result.activeMask=uint(a.z)|(uint(b.z)<<1)|(uint(c.z)<<2);
  return result;
}
bool FixClipOccluded(FixClipData data) {
  float epsilon=max(_OcclusionEpsilon,1e-7);
  // Negative denominators mean forward intersections: automatic at positive
  // FoV, required explicitly for the signed negative FoV convention.
  vec3 side=data.side+epsilon*abs(data.rayDenominator);
  return ((data.activeMask&1u)!=0u && data.rayDenominator.x< 0.0 && side.x>= 0.0) ||
         ((data.activeMask&2u)!=0u && data.rayDenominator.y< 0.0 && side.y>= 0.0) ||
         ((data.activeMask&4u)!=0u && data.rayDenominator.z< 0.0 && side.z>= 0.0);
}
bool FixOccluded(vec4 p, vec4 direction, float sine) {
  if(direction.w<= 0.0) return false;
  return FixClipOccluded(FixPrepareClips(p,-direction-sine*p,sine));
}
`;
